CREATE TABLE IF NOT EXISTS "Perfil" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"nombre" text,
	"rol" text,
	"alias" text,
	"resumen" text,
	"cv_url" text,
	"descripcion" text,
	"experiencia" text,
	"clientes" text,
	"proyectos" text,
	"telefono" text
);

ALTER TABLE "Perfil" ENABLE ROW LEVEL SECURITY;

